/**
 * Calculates the sum of each row in a 2D array of integers.
 *
 * @param array $matrix A 2D array of integers.
 * @return array An array containing the sum of each row.
 * @throws InvalidArgumentException If a row is not an array or contains non-integer values.
 */
function rowSums(array $matrix): array
{
    $sums = [];

    foreach ($matrix as $index => $row) {
        if (!is_array($row)) {
            throw new InvalidArgumentException("Row at index {$index} is not an array.");
        }

        $sum = 0;
        foreach ($row as $value) {
            if (!is_int($value)) {
                throw new InvalidArgumentException("Row at index {$index} contains a non-integer value.");
            }
            $sum += $value;
        }

        $sums[$index] = $sum;
    }

    return $sums;
}

