/**
 * Returns the sum of each row of a 2D array of integers.
 *
 * @param array<int, array<int, int>> $matrix
 * @return array<int, int>
 */
function sumRows(array $matrix): array
{
    $sums = [];

    foreach ($matrix as $row) {
        $sums[] = array_sum($row);
    }

    return $sums;
}

// Example
